function activeOnline(status){return ['link_gerado','link_aberto','aguardando_dados','aguardando_pagamento','preparando_link','pagamento_localizado_aguardando_processamento','sem_retorno_infinitepay'].includes(String(status||''))}
function paidStatus(status){return ['pago','pago_revisao','concluido_saldo','confirmado','confirmada','aplicado'].includes(String(status||'').toLowerCase())}
