function accountStudentV219(a={}){
 const ids=[a.alunoPrincipalId,...arr(a.alunosIds),String(a.id||'').startsWith('aluno_')?a.id:null].filter(Boolean);
 for(const id of ids){const found=(state.students||[]).find(x=>String(x.id)===String(id));if(found)return found}
 const rid=String(a.responsavelId||(String(a.id||'').startsWith('resp_')?a.id:'')||'');
 if(rid){const found=(state.students||[]).find(x=>x.ativo!==false&&studentFamilyKeyV219(x)===rid);if(found)return found}
 return null;
}
