 if(accountMode){await (window.ensureStudentsLoadedV218?.()||Promise.resolve());accounts=typeof window.loadAllFinancialAccountsV221==='function'?await window.loadAllFinancialAccountsV221():await financialAccountsRowsV167(true);const reg=await billingRegularizationsV221();links=reg.links;checkouts=reg.checkouts;hasMore=false}
 else{const [cp,lp]=await Promise.all([billingFetchPageV221('pagamentos_checkout',queryMode,reset),billingFetchPageV221('vendas_online_links',queryMode,reset)]);checkouts=[...cp.docs.values()];links=[...lp.docs.values()];hasMore=!cp.done||!lp.done;state.v221BillingMore=hasMore}
 const checkoutByNsu=new Map(checkouts.map(c=>[c.orderNsu||c.id,c]));const rows=[];
 for(const a of accounts){const net=accountNet(a);if(net<0||isBlocked(a)){const st=accountStudentV219(a),studentId=st?.id||a.alunoPrincipalId||arr(a.alunosIds)[0]||'',familyKey=billingFamilyKeyV219({account:a,studentRow:st});rows.push({key:`conta:${a.responsavelId||a.id}`,kind:'conta',kinds:[...(net<0?['saldo']:[]),...(isBlocked(a)?['bloqueada']:[])],familyKey,alunoId:studentId,alunoNome:st?.nome||'Conta familiar',matricula:st?.matricula||'',turma:st?.turma||'',account:a,totalCentavos:Math.max(0,-net),status:isBlocked(a)?'conta_bloqueada':'saldo_em_aberto',sortDate:a.atualizadoEm||a.bloqueadoEm||'1970-01-01'});}}
