 const accountByFamily=new Map(rows.filter(r=>r.kind==='conta'&&r.familyKey).map(r=>[r.familyKey,r]));for(const r of rows){if(r.kind==='conta'||!r.kinds.includes('pendente')||billingOperationV219(r)!=='regularizar_debito')continue;const acc=accountByFamily.get(r.familyKey);if(!acc)continue;(acc.regularizations||(acc.regularizations=[])).push(r);r.hiddenByAccount=true}for(const acc of accountByFamily.values()){if(!acc.regularizations?.length)continue;acc.regularizations.sort(byNewest);acc.regularization=acc.regularizations[0];if(!acc.kinds.includes('pendente'))acc.kinds.push('pendente');acc.sortDate=acc.regularization.sortDate||acc.sortDate}state.v221BillingMore=hasMore;return rows.sort(byNewest)
