async function loadSaleDeliveryContextV226(vendaId){
  const snap=await db.collection('ocorrencias_entrega').where('vendaId','==',String(vendaId)).get();
  return snap.docs.map(d=>({id:d.id,...(d.data()||{})})).sort((a,b)=>String(a.dataChave||'').localeCompare(String(b.dataChave||'')));
}
function deliveryDateLabelV226(o={}){try{return typeof datePtV151==='function'?datePtV151(o.dataChave,true):String(o.dataChave||'Data não informada')}catch(_){return String(o.dataChave||'Data não informada')}}
function deliveryItemsLabelV226(o={}){const items=arr(o.itens).map(i=>`${i.quantidade||1}× ${i.nome||'Item'}`);return items.join(' · ')||'Entrega de cantina'}
function deliveryCorrectionHtmlV226(rows=[],prefix='v222'){
  const delivered=arr(rows).filter(o=>String(o.status||'').toLowerCase()==='entregue');
  const advanced=arr(rows).filter(o=>!['','pendente_entrega','programado','cancelado','entregue'].includes(String(o.status||'').toLowerCase()));
  const advancedHtml=advanced.length?`<div class="alert warn" style="margin-top:12px"><strong>Há atendimento já finalizado por outro motivo.</strong><br>${advanced.map(o=>`${esc(deliveryDateLabelV226(o))}: ${esc(fmtStatus(o.status))}`).join('<br>')}<br><span class="muted">Esse tipo de ocorrência continua protegido contra cancelamento automático para evitar crédito ou estoque em duplicidade.</span></div>`:'';
  if(!delivered.length)return `${advancedHtml}<label class="switch-line v226-confirm-line"><div><strong>Nenhuma entrega foi realizada</strong><div class="muted">Confirmo que nenhum item, lanche, farda, serviço ou credencial desta venda foi efetivamente entregue ou utilizado.</div></div><input id="${prefix}NoDelivery" type="checkbox"></label>`;
  return `${advancedHtml}<div class="v226-delivery-box"><div class="v226-delivery-head"><strong>O sistema encontrou ${delivered.length} entrega${delivered.length>1?'s':''} marcada${delivered.length>1?'s':''} como entregue.</strong><span>Se a Cantina marcou por engano, confirme cada ocorrência abaixo. O registro original será preservado na auditoria e a entrega será anulada junto com a venda.</span></div>${delivered.map(o=>`<label class="v226-delivery-row"><div><strong>${esc(deliveryDateLabelV226(o))}</strong><span>${esc(deliveryItemsLabelV226(o))}${o.alunoNome?` · ${esc(o.alunoNome)}`:''}</span><small>Confirmo: foi marcada como entregue por engano e o item não foi realmente entregue.</small></div><input type="checkbox" data-v226-delivery-prefix="${prefix}" value="${esc(o.id)}"></label>`).join('')}</div>`;
}
function selectedDeliveryMistakesV226(prefix){return [...document.querySelectorAll(`[data-v226-delivery-prefix="${prefix}"]:checked`)].map(x=>String(x.value||'')).filter(Boolean)}
function requiredDeliveryMistakesV226(prefix){return [...document.querySelectorAll(`[data-v226-delivery-prefix="${prefix}"]`)].map(x=>String(x.value||'')).filter(Boolean)}
function validateDeliveryCorrectionV226(prefix){const required=requiredDeliveryMistakesV226(prefix),selected=selectedDeliveryMistakesV226(prefix);if(required.length&&selected.length!==required.length)return{ok:false,ids:selected,message:'Para cancelar toda a venda, confirme todas as entregas que aparecem como “Entregue”. Se alguma delas foi realmente entregue, esta venda não pode ser anulada por este fluxo.'};if(!required.length&&$(`#${prefix}NoDelivery`)?.checked!==true)return{ok:false,ids:[],message:'Confirme que nenhum item ou serviço desta venda foi efetivamente entregue ou utilizado.'};return{ok:true,ids:selected}}

async function openCancelInPersonSaleV222(vendaId){
  const row=arr(state.v162SalesRows).find(x=>x.sale?.id===vendaId);if(!row?.sale)return appMessage('Venda não localizada no histórico carregado.');
  const s=row.sale;let deliveries=[];try{deliveries=await loadSaleDeliveryContextV226(vendaId)}catch(e){return appMessage('Não foi possível conferir as entregas vinculadas a esta venda. Atualize a tela e tente novamente.')}
  openModal('Cancelar venda presencial',`<div class="v226-cancel-note"><strong>Correção de venda</strong><span>A venda original será preservada. O sistema desfará os efeitos financeiros e, quando uma entrega tiver sido marcada por engano, poderá corrigir também essa entrega.</span></div><div class="v162-detail-grid" style="margin-top:12px"><div><small>Aluno</small><strong>${esc(s.alunoNome||row.alunoNome||'-')}</strong></div><div><small>Valor</small><strong>${fmt(s.valorBrutoCentavos||row.totalCentavos)}</strong></div><div><small>Forma registrada</small><strong>${esc(prettify(s.formaPagamento||'-'))}</strong></div><div><small>Venda</small><strong>${esc(s.id)}</strong></div></div><div class="fg" style="margin-top:14px"><label>Motivo do cancelamento</label><select id="v222CancelReason" class="fi"><option value="pagamento_nao_recebido">Pagamento confirmado por engano / valor não recebido</option><option value="registro_duplicado">Registro duplicado</option><option value="venda_lancada_por_engano">Venda lançada por engano</option><option value="outro_erro_operacional">Outro erro operacional</option></select></div><div class="fg"><label>Observação</label><textarea id="v222CancelDetail" class="fi" rows="3" placeholder="Explique resumidamente o ocorrido"></textarea></div><label class="switch-line v226-confirm-line"><div><strong>Não existe valor externo a devolver</strong><div class="muted">Se o sistema marcou dinheiro, Pix ou cartão como recebido, esse valor não entrou de fato.</div></div><input id="v222CancelNoRefund" type="checkbox"></label>${deliveryCorrectionHtmlV226(deliveries,'v222')}<div id="v222CancelStatus"></div><div class="actions" style="margin-top:14px"><button class="btn btn-outline" onclick="closeModal()">Voltar</button><button id="v222CancelBtn" class="btn v226-danger-soft" onclick="confirmCancelInPersonSaleV222('${safeJs(vendaId)}')">Cancelar venda e corrigir efeitos</button></div>`)
}
async function confirmCancelInPersonSaleV222(vendaId){
  const btn=$('#v222CancelBtn'),host=$('#v222CancelStatus'),reason=$('#v222CancelReason')?.value,details=$('#v222CancelDetail')?.value?.trim()||'',noRefund=$('#v222CancelNoRefund')?.checked===true,delivery=validateDeliveryCorrectionV226('v222');
  if(!noRefund){if(host)host.innerHTML='<div class="alert warn" style="margin-top:12px">Confirme que não existe valor externo a reembolsar.</div>';return}
  if(!delivery.ok){if(host)host.innerHTML=`<div class="alert warn" style="margin-top:12px">${esc(delivery.message)}</div>`;return}
  if(!await appConfirm('A venda será cancelada e os efeitos financeiros serão revertidos. Entregas selecionadas como marcadas por engano também serão anuladas, mantendo o histórico para auditoria.',{title:'Confirmar correção da venda?',confirmLabel:'Confirmar cancelamento',cancelLabel:'Voltar'}))return;
  try{
    if(btn){btn.disabled=true;btn.textContent='Cancelando...'}
    const token=await authObjV130().currentUser?.getIdToken(),resp=await fetch('/api/cancelar-venda-presencial',{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:JSON.stringify({vendaId,motivo:reason,detalhes:details,confirmoSemReembolso:true,confirmoSemEntrega:true,confirmoEntregaMarcadaPorEngano:delivery.ids.length>0,entregasMarcadasPorEnganoIds:delivery.ids})}),data=await resp.json().catch(()=>({}));
    if(!resp.ok){const blockers=arr(data.details?.blockers);throw new Error(`${data.error||'Não foi possível cancelar.'}${blockers.length?`\n\n${blockers.join('\n')}`:''}`)}
    closeModal();state.v221SalesPager=null;try{sessionStorage.removeItem('piaget:v221:dashboard')}catch(_){ }
    const corrected=Number(data.quantidadeEntregasEstornadas||0);toast(data.alreadyCancelled?'A venda já estava cancelada.':corrected?`Venda cancelada e ${corrected} entrega${corrected>1?'s':''} marcada${corrected>1?'s':''} por engano corrigida${corrected>1?'s':''}.`:'Venda cancelada e estornos registrados.');
    await renderVendasV162('presencial',{refresh:true})
  }catch(e){if(host)host.innerHTML=`<div class="alert danger" style="margin-top:12px;white-space:pre-line">${esc(e.message)}</div>`;else appMessage(e.message);if(btn){btn.disabled=false;btn.textContent='Cancelar venda e corrigir efeitos'}}
}

window.openCancelInPersonSaleV222=openCancelInPersonSaleV222;window.confirmCancelInPersonSaleV222=confirmCancelInPersonSaleV222;

