async function renewOnlineLinkV162(id){const c=checkoutForLinkV218(id);if(checkoutReconciliationRiskV218(c||{}))return appMessage('Esta cobrança está em verificação. Não gere outro link até confirmar se o pagamento original foi realizado.');const a=state.user||{},r=await fetch('/api/gerenciar-venda-online',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'renovar',id,criadoPorId:a.id,criadoPorNome:a.nome})}),d=await r.json().catch(()=>({}));if(!r.ok)return appMessage(d.error||'Não foi possível gerar um novo link.');showOnlineLinkV162(d.url,d.id)}

