async function openParentMovementsV162(){const a=state.parentStudent;openModal('Movimentações da conta','<div class="v151-inline-loader">Carregando movimentações...</div>');try{const [ms,cs]=await Promise.all([db.collection('movimentos_conta').where('alunoId','==',a.id).limit(200).get(),db.collection('pagamentos_checkout').where('alunoId','==',a.id).limit(80).get().catch(()=>({docs:[]}))]);const rows=ms.docs.map(d=>({id:d.id,...d.data()})).sort(byNewest),checkouts=cs.docs.map(d=>({id:d.id,...d.data()}));state.v162ParentMoves=rows;$('#modalBody').innerHTML=rows.length?`<div class="v151-list">${rows.map(m=>{const v=movementSignedV162(m),checkout=checkouts.find(c=>(m.orderNsu&&(c.orderNsu||c.id)===m.orderNsu)||(m.pedidoId&&c.pedidoId===m.pedidoId)),orderNsu=m.orderNsu||checkout?.orderNsu||checkout?.id||'',lines=arr(m.itens),preview=lines.slice(0,2).map(x=>`${itemQty(x)}× ${itemName(x)} — ${fmt(itemTotal(x))}`).join(' · ');return `<div class="v151-ledger-card v162-parent-ledger"><div><strong>${humanDate(m.criadoEm)}</strong><div class="muted" style="font-size:11px">${esc(prettify(m.formaPagamento||m.origem||'-'))}</div></div><div><strong>${esc(movementTitleV162(m))}</strong><div class="muted" style="font-size:12px;margin-top:3px">${preview?esc(preview):(m.descricao?esc(m.descricao):'Valor global da movimentação')}</div>${m.saldoDepoisCentavos!==undefined?`<div class="muted" style="font-size:11px;margin-top:4px">Saldo após: ${m.saldoDepoisCentavos>=0?'+':''}${fmt(m.saldoDepoisCentavos)}</div>`:''}<div class="actions" style="margin-top:7px"><button class="btn btn-light" onclick="openMovementDetailV162('${safeJs(m.id)}','parent')">Detalhar</button>${orderNsu?`<button class="btn btn-outline" onclick="openParentReceiptMenuV156('${safeJs(m.id)}','${safeJs(orderNsu)}')">Comprovante</button>`:''}</div></div><div class="amount ${v>=0?'in':'out'}">${v>=0?'+':''}${fmt(v)}</div></div>`}).join('')}</div>`:'<div class="empty">Nenhuma movimentação registrada.</div>'}catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}}

/* CONTA ADMINISTRATIVA DO ALUNO */
async function studentRowsV220(collection,id,limit=50,orderField='criadoEm'){
 const q=db.collection(collection).where('alunoId','==',id);try{return (await q.orderBy(orderField,'desc').limit(limit).get()).docs.map(d=>({id:d.id,...d.data()}))}catch(e){console.warn('studentRowsV220 fallback',collection,e?.message||e);return (await q.limit(limit).get().catch(()=>({docs:[]}))).docs.map(d=>({id:d.id,...d.data()}))}
}
async function ensureStudentTabDataV220(tab,d){
 d._loaded=d._loaded||{};d._deep=d._deep||{};if(d._loaded[tab])return;const deep=Boolean(d._deep[tab]);
 if(tab==='resumo'){
  const [os,ps,fs,ls,ms]=await Promise.all([studentRowsV220('ocorrencias_entrega',d.id,12,'dataChave'),studentRowsV220('pedidos',d.id,8),studentRowsV220('pedidos_farda',d.id,8),studentRowsV220('vendas_online_links',d.id,8,'atualizadoEm'),studentRowsV220('movimentos_conta',d.id,8)]);
  d.occurrences=os.sort((x,y)=>String(x.dataChave||'').localeCompare(String(y.dataChave||'')));d.orders=ps.map(x=>({...x,tipoPedido:'cantina'})).sort(byNewest);d.uniforms=fs.map(x=>({...x,tipoPedido:'farda'})).sort(byNewest);d.links=ls.sort(byNewest);d.moves=ms.sort(byNewest);d.checkouts=d.checkouts||[];d.sales=d.sales||[];
 }else if(tab==='lanches'){d.occurrences=(await studentRowsV220('ocorrencias_entrega',d.id,deep?150:50,'dataChave')).sort((x,y)=>String(y.dataChave||'').localeCompare(String(x.dataChave||'')))}
 else if(tab==='pedidos'){const [ps,fs]=await Promise.all([studentRowsV220('pedidos',d.id,deep?120:40),studentRowsV220('pedidos_farda',d.id,deep?80:30)]);d.orders=ps.map(x=>({...x,tipoPedido:'cantina'})).sort(byNewest);d.uniforms=fs.map(x=>({...x,tipoPedido:'farda'})).sort(byNewest)}
 else if(tab==='movimentos'){d.moves=(await studentRowsV220('movimentos_conta',d.id,deep?150:50)).sort(byNewest)}
 else if(tab==='pagamentos'){const [ls,cs]=await Promise.all([studentRowsV220('vendas_online_links',d.id,deep?100:40,'atualizadoEm'),studentRowsV220('pagamentos_checkout',d.id,deep?100:40,'atualizadoEm')]);d.links=ls.sort(byNewest);d.checkouts=cs.sort(byNewest)}
 d._loaded[tab]=true;
}
async function openStudentDetailsV162(id){const a=student(id);openModal('Conta do aluno','<div class="v151-inline-loader">Carregando resumo da conta...</div>');try{const acc=await getAccount(id),data={id,student:a,account:acc,moves:[],orders:[],uniforms:[],occurrences:[],links:[],checkouts:[],sales:[],_loaded:{},_deep:{}};state.v162StudentAccount=data;$('#modalBody').innerHTML=`<div class="v162-student-head"><div><span>${esc(a.turma||'-')} · Matrícula ${esc(a.matricula||'-')}</span><strong>${esc(a.nome||id)}</strong><small>Responsável: ${esc(a.responsavelFinanceiro||'-')}</small></div><span class="badge ${isBlocked(acc)?'b-red':'b-green'}">${isBlocked(acc)?'Conta bloqueada':'Conta liberada'}</span></div><div class="v162-student-tabs"><button onclick="renderStudentAccountTabV162('resumo')">Resumo</button><button onclick="renderStudentAccountTabV162('lanches')">Lanches</button><button onclick="renderStudentAccountTabV162('pedidos')">Pedidos</button><button onclick="renderStudentAccountTabV162('movimentos')">Movimentações</button><button onclick="renderStudentAccountTabV162('pagamentos')">Pagamentos</button></div><div id="v162StudentAccountBody"></div>`;document.querySelector('.modal')?.classList.add('v162-modal-wide');await renderStudentAccountTabV162('resumo')}catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}}

function studentBalanceHtmlV162(d){const net=accountNet(d.account);return `<div class="v162-balance-grid"><div><small>Saldo da conta</small><strong class="${net>=0?'v162-positive':'v162-negative'}">${net>=0?'+':''}${fmt(net)}</strong></div><div><small>Crédito disponível</small><strong>${fmt(Math.max(0,net))}</strong></div><div><small>Saldo em aberto</small><strong>${fmt(Math.max(0,-net))}</strong></div><div><small>Limite</small><strong>${fmt(d.account.limiteFiadoCentavos||0)}</strong></div></div>`}
function occurrenceCardV162(o){return `<div class="v162-mini-card"><div><strong>${esc(o.dataChave||'-')}</strong><span>${arr(o.itens).map(x=>`${itemQty(x)}× ${itemName(x)}`).join(', ')||'Lanche programado'}</span></div><span class="badge ${statusClass(o.status)}">${esc(prettify(o.status||'programado'))}</span></div>`}
function orderCardV162(o){const isUniform=o.tipoPedido==='farda',status=isUniform?(o.statusAtendimento||o.statusPagamento):(o.statusPedido||o.statusPagamento),title=isUniform?(o.produto||'Fardamento'):(o.modalidade==='mensal'?'Lanches do mês':o.modalidade==='semanal'?'Lanches da semana':'Pedido de cantina');return `<div class="v162-mini-card"><div><strong>${esc(title)}</strong><span>${humanDate(o.criadoEm)} · ${fmt(o.totalCentavos||0)}</span></div><div><span class="badge ${statusClass(status)}">${esc(prettify(status))}</span><button class="btn btn-light" onclick="openAdminOrderDetailV162('${isUniform?'farda':'cantina'}','${safeJs(o.id)}')">Detalhar</button></div></div>`}
function movementCardsV162(moves,limit=999){return arr(moves).slice(0,limit).map(m=>{const v=movementSignedV162(m);return `<div class="v162-mini-card"><div><strong>${esc(movementTitleV162(m))}</strong><span>${humanDate(m.criadoEm)} · ${v>=0?'+':''}${fmt(v)}</span></div><button class="btn btn-light" onclick="openMovementDetailV162('${safeJs(m.id)}','staff')">Detalhar</button></div>`}).join('')||'<div class="empty-soft">Nenhuma movimentação.</div>'}
function paymentCardsV162(d,limit=999){const rows=[...d.links.map(l=>({kind:'link',id:l.id,status:l.status,total:n(l.totalCentavos),sortDate:l.pagoEm||l.criadoEm,orderNsu:l.orderNsu||'',raw:l})),...d.checkouts.filter(c=>!d.links.some(l=>l.orderNsu&&(l.orderNsu===(c.orderNsu||c.id)))).map(c=>({kind:'checkout',id:c.id,status:c.statusAplicacao==='aplicado'?'pago':c.status,total:n(c.pedidoTotalCentavos||c.totalCentavos),date:c.pagamentoConfirmadoEm||c.criadoEm,orderNsu:c.orderNsu||c.id,raw:c}))].sort(byNewest).slice(0,limit);state.v162StudentPayments=rows;return rows.map((p,i)=>`<div class="v162-mini-card"><div><strong>${esc(operationTitle(p.raw.operacao||p.raw.tipo))}</strong><span>${humanDate(p.sortDate)} · ${fmt(p.total)}</span></div><div><span class="badge ${statusClass(p.status)}">${esc(p.kind==='link'?onlineLabel(p.status):checkoutLabel(p.status))}</span>${p.orderNsu&&paidStatus(p.status)?`<button class="btn btn-green" onclick="openReceiptV142('${safeJs(p.orderNsu)}')">Comprovante</button>`:''}</div></div>`).join('')||'<div class="empty-soft">Nenhum pagamento.</div>'}
async function renderStudentAccountTabV162(tab='resumo'){const d=state.v162StudentAccount,h=$('#v162StudentAccountBody');if(!d||!h)return;document.querySelectorAll('.v162-student-tabs button').forEach(b=>b.classList.toggle('active',b.textContent.toLowerCase().startsWith(tab==='movimentos'?'movimenta':tab)));h.innerHTML='<div class="v151-inline-loader">Carregando somente este bloco...</div>';try{await ensureStudentTabDataV220(tab,d)}catch(e){h.innerHTML=`<div class="alert danger">${esc(e.message||'Não foi possível carregar este bloco.')}</div>`;return}const today=dateKey(),future=arr(d.occurrences).filter(o=>String(o.dataChave||'')>=today&&!['cancelado','entregue','ausente','aluno_ausente','nao_entregue'].includes(o.status)),openOrders=[...arr(d.orders),...arr(d.uniforms)].filter(o=>!['concluido','entregue','cancelado','nao_concluido'].includes(String(o.statusPedido||o.statusAtendimento||o.statusPagamento||''))),pending=arr(d.links).filter(l=>activeOnline(l.status));if(tab==='resumo'){h.innerHTML=`${studentBalanceHtmlV162(d)}<div class="actions v162-student-actions"><button class="btn btn-primary" onclick="openAccountPaymentV141('${safeJs(d.id)}','staff')">Gerar cobrança</button><button class="btn btn-green" onclick="registerManualPaymentV141('${safeJs(d.id)}')">Registrar pagamento</button><button class="btn btn-outline" onclick="toggleManualBlock('${safeJs(d.id)}',${!d.account.bloqueioManual})">${d.account.bloqueioManual?'Remover bloqueio':'Bloquear conta'}</button><button class="btn btn-light" onclick="generateReport('${safeJs(d.id)}')">Relatório</button><button class="btn btn-light" onclick="openEditResponsibleV223('${safeJs(d.id)}')">Editar responsável</button><button class="btn btn-light" onclick="openStudentCreditV223('${safeJs(d.id)}')">Autorização de consumo</button></div><div class="v162-overview-grid"><section><div class="card-title">Próximos lanches</div>${future.slice(0,4).map(occurrenceCardV162).join('')||'<div class="empty-soft">Nenhum lanche programado.</div>'}</section><section><div class="card-title">Pedidos em aberto</div>${openOrders.slice(0,4).map(orderCardV162).join('')||'<div class="empty-soft">Nenhum pedido em aberto.</div>'}</section><section><div class="card-title">Links pendentes</div>${pending.slice(0,4).map(l=>`<div class="v162-mini-card"><div><strong>${esc(operationTitle(l.operacao))}</strong><span>${fmt(l.totalCentavos||0)}</span></div><button class="btn btn-light" onclick="window.open('${safeJs(l.urlInterna||'#')}','_blank')">Abrir</button></div>`).join('')||'<div class="empty-soft">Nenhum link pendente.</div>'}</section><section><div class="card-title">Movimentações recentes</div>${movementCardsV162(d.moves,4)}</section></div><div class="muted" style="margin-top:10px">O resumo carrega apenas blocos recentes. As abas abaixo fazem consultas específicas quando abertas.</div>`;return}const deep=Boolean(d._deep?.[tab]),more=`<div style="text-align:center;margin-top:12px"><button class="btn btn-outline" onclick="expandStudentTabV220('${tab}')">${deep?'Atualizar bloco ampliado':'Carregar mais histórico'}</button></div><div class="muted" style="margin-top:8px">${deep?'Bloco ampliado carregado.':'Exibição em bloco para preservar desempenho; use “Carregar mais histórico” quando precisar investigar períodos anteriores.'}</div>`;if(tab==='lanches'){h.innerHTML=`<div class="card-title">Lanches programados e entregas</div>${d.occurrences.length?d.occurrences.map(occurrenceCardV162).join(''):'<div class="empty">Nenhum lanche programado.</div>'}${more}`;return}if(tab==='pedidos'){h.innerHTML=`<div class="card-title">Pedidos do aluno</div>${[...d.orders,...d.uniforms].sort(byNewest).map(orderCardV162).join('')||'<div class="empty">Nenhum pedido.</div>'}${more}`;return}if(tab==='movimentos'){h.innerHTML=`<div class="card-title">Extrato e composição</div>${movementCardsV162(d.moves)}${more}`;return}h.innerHTML=`<div class="card-title">Links, pagamentos e comprovantes</div>${paymentCardsV162(d)}${more}`}
window.expandStudentTabV220=async function(tab){const d=state.v162StudentAccount;if(!d)return;d._deep=d._deep||{};d._loaded=d._loaded||{};d._deep[tab]=true;d._loaded[tab]=false;await renderStudentAccountTabV162(tab)};

