window.confirmRefundSaleV224=async function(vendaId){const done=$('#v224RefundDone')?.checked===true,delivery=validateDeliveryCorrectionV226('v224Refund'),method=$('#v224RefundMethod')?.value||'',ref=String($('#v224RefundRef')?.value||'').trim(),reason=$('#v224RefundReason')?.value||'',detail=String($('#v224RefundDetail')?.value||'').trim(),btn=$('#v224RefundBtn'),host=$('#v224RefundStatus');if(!done)return appMessage('Confirme que a devolução ao pagador já foi realizada.');if(!delivery.ok)return appMessage(delivery.message);if(method!=='dinheiro'&&ref.length<3)return appMessage('Informe a referência/comprovante do reembolso para preservar a auditoria.');try{if(btn){btn.disabled=true;btn.textContent='Registrando reembolso...'}const token=await auth.currentUser?.getIdToken?.(),r=await fetch('/api/cancelar-venda-presencial',{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:JSON.stringify({vendaId,tipoOperacao:'reembolso_recebido',motivo:reason,detalhes:detail,formaReembolso:method,referenciaReembolso:ref,confirmoReembolsoExterno:true,confirmoSemEntrega:true,confirmoEntregaMarcadaPorEngano:delivery.ids.length>0,entregasMarcadasPorEnganoIds:delivery.ids})}),d=await r.json().catch(()=>({}));if(!r.ok){const blockers=arr(d.details?.blockers);throw new Error(`${d.error||'Não foi possível registrar o reembolso.'}${blockers.length?`\n\n${blockers.join('\n')}`:''}`)}closeModal();state.v221SalesPager=null;state.v221BillingPager=null;try{sessionStorage.removeItem('piaget:v221:dashboard')}catch(_){}const corrected=Number(d.quantidadeEntregasEstornadas||0);toast(d.alreadyCancelled?'A venda já estava cancelada/estornada.':corrected?`Venda cancelada, reembolso registrado e ${corrected} entrega${corrected>1?'s':''} corrigida${corrected>1?'s':''}.`:'Venda cancelada e reembolso registrado.');if(state.v162CurrentView==='cobrancas')await renderCobrancasV162(state.v162BillingFilter||'hoje');else await renderVendasV162(state.v162SalesFilter||'todos',{refresh:true})}catch(e){if(host)host.innerHTML=`<div class="alert danger" style="margin-top:12px;white-space:pre-line">${esc(e.message)}</div>`;else appMessage(e.message);if(btn){btn.disabled=false;btn.textContent='Registrar cancelamento e reembolso'}}}

